package org.example;

import org.example.cli.TodoConsole;
import org.example.cli.printer.BoardPrinter;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.ResolverStyle;
import java.util.ArrayList;
import java.util.Map;
import java.util.Scanner;

public class App {
    public static Scanner scanner = new Scanner(System.in);

    public String getGreeting() {
        return "Hello World!";
    }

    public static void main(String[] args) {
        mainLoop();
    }

    public static void mainLoop() {
        Board MainBoard = new Board(0, 1, "Main Board", "Geral tasks");
        Task testTask = new Task(0, 1, "TaskTeste", "desc1", "23/12/2026 12:00", "CategoriaTeste");

        MainBoard.addTask(testTask);
        TodoConsole todoConsole = new TodoConsole();

        Thread alarmThread = new Thread(new Alarm(MainBoard, 1000));
        alarmThread.setDaemon(true);
        alarmThread.start();

        int choice;
        while (true) {
            todoConsole.menu();
            choice = readInt();
            switch (choice) {
                case 1:
                    createTask(MainBoard);

                    break;
                case 2:
                    listTasksMenu(MainBoard);
                    break;
                case 3:
                    scanner.nextLine();
                    BoardPrinter.printBoard(MainBoard);
                    while (true) {
                        System.out.println("Please enther the name of task to update: ");

                        String taskName = scanner.nextLine();

                        Task tempTask = MainBoard.findTask(taskName);
                        tempTask = MainBoard.findTask(taskName);

                        MainBoard.moveTask(tempTask);

                        if (tempTask != null) {
                            break;
                        }
                    }
                    break;
                case 4:
                    scanner.nextLine();
                    BoardPrinter.printBoard(MainBoard);
                    while (true) {
                        System.out.println("Please enther the name of task to remove: ");

                        String taskName = scanner.nextLine();

                        Task tempTask = MainBoard.findTask(taskName);
                        tempTask = MainBoard.findTask(taskName);

                        MainBoard.removeTask(tempTask);

                        if (tempTask != null) {
                            break;
                        }
                    }
                    break;
                case 5:
                    alarmMenu(MainBoard);
                    break;
                case 0:
                    //break looping
                    System.out.println("Saindo...");
                    return;
                default:
                    System.out.println("Wrong choice");
                    break;
            }
        }
    }

    public static void createTask(Board board) {
        scanner.nextLine();
        System.out.println("Enter task name: ");
        String taskName = scanner.nextLine();
        System.out.println("Enter task description: ");
        String taskDescription = scanner.nextLine();
        System.out.println("Enter task priority: ");
        int taskPriority = readInt();
        scanner.nextLine();
        System.out.println("Enter task category: ");
        String taskCategory = scanner.nextLine();
        System.out.println("Enter the target date (dd/MM/yyyy HH:mm): ");
        String targetDate = scanner.nextLine();
        if (!isDataValid(targetDate)) {
            while (true) {
                System.out.println("Invalid date format, try again:");
                targetDate = scanner.nextLine();
                if (isDataValid(targetDate)) {
                    break;
                }
            }
        }

        Task tempTask = new Task(0, taskPriority, taskName, taskDescription, targetDate, taskCategory);
        board.addTask(tempTask);
        System.out.println("Task has been created");
    }

    public static void listTasksMenu(Board board) {
        scanner.nextLine();

        System.out.println("Listar tarefas");
        System.out.println("[1] - Todas");
        System.out.println("[2] - Por status");
        System.out.println("[3] - Por prioridade");
        System.out.println("[4] - Por categoria");
        System.out.println("[0] - Voltar");

        try {

            int choice = readInt();
            scanner.nextLine();

            switch (choice) {
                case 1:
                    listTasks(board);
                    break;
                case 2:
                    listTasksByStatus(board);
                    break;
                case 3:
                    BoardPrinter.printSection("Tasks by priority", board.getTasksByPriority());
                    break;
                case 4:
                    System.out.println("Enter category: ");
                    String category = scanner.nextLine();
                    BoardPrinter.printSection("Category: " + category, board.getTasksByCategory(category));
                    break;
                case 0:
                    break;
                default:
                    System.out.println("Wrong choice");
                    break;
            }
        } catch (Exception e) {
            System.out.println("Invalid input. Please enter a number.");
            scanner.nextLine(); // Clear the invalid input
        }
    }

    public static void listTasksByStatus(Board board) {
        System.out.println("Escolha o status");
        System.out.println("[1] - ToDo");
        System.out.println("[2] - Doing");
        System.out.println("[3] - Done");
        System.out.println("[0] - Voltar");

        int choice = readInt();
        scanner.nextLine();

        switch (choice) {
            case 1:
                BoardPrinter.printSection("ToDo", board.getTasksByStatus("ToDo"));
                break;
            case 2:
                BoardPrinter.printSection("Doing", board.getTasksByStatus("Doing"));
                break;
            case 3:
                BoardPrinter.printSection("Done", board.getTasksByStatus("Done"));
                break;
            case 0:
                break;
            default:
                System.out.println("Wrong choice");
                break;
        }
    }

    public static void listTasks(Board board) {
        BoardPrinter.printBoard(board);
    }

    public static int readInt() {
        while (!scanner.hasNextInt()) {
            System.out.println("Invalid input. Please enter a number.");
            scanner.nextLine();
        }

        return scanner.nextInt();
    }

    /**
     * dado uma data no formato dd/MM/yyyy HH:mm, verifica se a data é válida e se é maior ou igual a data atual
     *
     * @param data
     * @return
     */
    public static boolean isDataValid(String data) {
        try {
            DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd/MM/uuuu HH:mm")
                    .withResolverStyle(ResolverStyle.STRICT);
            LocalDateTime enteredDate = LocalDateTime.parse(data, formatter);

            LocalDateTime today = LocalDateTime.now();

            return !enteredDate.isBefore(today);
        } catch (Exception e) {
            return false;
        }

    }

    /**
     * dado uma data no formato LocalDateTime, verifica se a data é maior ou igual a data atual
     *
     * @param data
     * @return
     */
    public static boolean isDataValid(LocalDateTime data) {
        try {
            LocalDateTime today = LocalDateTime.now();

            return !data.isBefore(today);
        } catch (Exception e) {
            return false;
        }

    }

    public static void alarmMenu(Board board) {
        System.out.println("[1] - Criar alarme");
        System.out.println("[2] - Listar alarmes");
        System.out.println("[0] - Voltar");

        int choice = readInt();
        scanner.nextLine();

        switch (choice) {
            case 1:
                System.out.println("Insira o nome da task que deseja adicionar o alarme: ");
                String taskName = scanner.nextLine();
                Task task = board.findTask(taskName);
                if (task == null) {
                    System.out.println("Tarefa não encontrada");
                    return;
                }

                if (task.getSection().equals("Done")) {
                    System.out.println("Não é possível adicionar alarme para tarefas concluídas.");
                    return;
                }
                BoardPrinter.printTask(task);

                System.out.println("Quantos minutos antes da task deseja receber o alarme? ");

                int minutesBefore = readInt();
                while (minutesBefore <=0){
                    System.out.println("O valor deve ser maior que 0, tente novamente: ");
                    minutesBefore = readInt();
                }

                DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd/MM/uuuu HH:mm")
                        .withResolverStyle(ResolverStyle.STRICT);
                LocalDateTime targetDate = LocalDateTime.parse(task.getTarget_data(), formatter);
                LocalDateTime alarmTime = targetDate.minusMinutes(minutesBefore);

                if (isDataValid(alarmTime)) {
                    task.addAlarmTime(alarmTime);
                    System.out.println("Alarme configurado para: " + alarmTime.format(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm")));
                } else {
                    System.out.println("Alarme não pode ser configurado para uma data passada.");
                    return;
                }
                break;
            case 2:
                boolean hasAlarms = false;
                // Listar alarmes
                for (Task currentTask : board.getAllTasks()) {
                    if (!currentTask.getAlarmTimes().isEmpty()) {
                        BoardPrinter.printTask(currentTask);
                        for (LocalDateTime currentAlarmTime : currentTask.getAlarmTimes()) {
                            System.out.println("\t\tAlarme: " + currentAlarmTime.format(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm")));
                        }
                        hasAlarms = true;
                    }
                }
                if (!hasAlarms) {
                    System.out.println("Nenhum alarme encontrado.");
                }

                break;
            case 0:
                // Voltar
                break;
            default:
                System.out.println("Wrong choice");
                break;
        }
    }
}
